* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fb; color: #202938; font: 16px/1.5 system-ui, sans-serif; }
main { width: min(720px, calc(100% - 32px)); margin: 64px auto; }
section { padding: 32px; background: white; border: 1px solid #e1e6ee; border-radius: 12px; box-shadow: 0 8px 24px #26354a0a; }
h1 { margin: 0 0 24px; font-size: 2rem; }
label { display: block; margin-bottom: 8px; font-weight: 600; }
.form-row, .project-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
input { min-width: 0; flex: 1; padding: 10px 12px; border: 1px solid #aeb8c7; border-radius: 6px; font: inherit; }
input[type="checkbox"] { min-width: auto; flex: 0 0 auto; width: 20px; height: 20px; }
select { padding: 8px 12px; border: 1px solid #aeb8c7; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #315dcc; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #254ba9; }
.project-row { padding: 16px 0; border-bottom: 1px solid #e6eaf0; }
.project-row:first-child { margin-top: 20px; }
#alert { color: #b42318; margin-bottom: 0; }
[hidden] { display: none !important; }
@media (max-width: 480px) { main { margin: 24px auto; } section { padding: 22px; } .form-row { align-items: stretch; flex-direction: column; } }

